-- Official platform content for five centers (كفاءة - محتوى المراكز للمنصة.xlsx):
-- overview, outputs, methodology and target audience; the short card text is regenerated from the overview.
-- Status, price, services and extra services are left as they are. Centers are matched by title, so a
-- database without one of them is simply not changed. The migration runner executes this file in a transaction.

UPDATE enablement_centers SET
    overview = $c$يقدّم حزمة مترابطة لبناء المنظومة المؤسسية للجمعية، تبدأ بفهم واقعها وتحديد توجهها، وتشمل تنظيم الأدوار والصلاحيات، وتطوير السياسات والإجراءات، وإعداد أدوات التخطيط والمتابعة. ويساعد على ربط هذه المكونات ببعضها، بما يوضح المسؤوليات، ويحدّ من تداخل الأعمال، ويدعم قدرة الجمعية على إدارة أنشطتها ومتابعة تقدمها.$c$,
    short_description = $c$يقدّم حزمة مترابطة لبناء المنظومة المؤسسية للجمعية، تبدأ…$c$,
    outputs = $c$["تقرير الوضع الراهن وأولويات التطوير.","الخطة الاستراتيجية والخطة التشغيلية السنوية.","الهيكل التنظيمي والأوصاف الوظيفية ومصفوفة الصلاحيات.","السياسات والإجراءات التشغيلية والنماذج الإدارية.","لوحة متابعة المؤشرات وإرشادات تحديثها."]$c$::jsonb,
    methodology = $c$[{"title":"تحليل الوضع المؤسسي","description":"دراسة وثائق الجمعية وممارساتها ومواردها، وتحديد الفجوات في الحوكمة والتنظيم والتشغيل وأولويات معالجتها."},{"title":"بناء التوجه الاستراتيجي","description":"تحليل البيئة واحتياجات أصحاب المصلحة، وصياغة التوجهات والأهداف والنتائج المستهدفة والمؤشرات والمبادرات."},{"title":"تصميم البناء التنظيمي","description":"تحديد الوحدات والاختصاصات وعلاقات الإشراف، وإعداد الأوصاف الوظيفية ومعالجة التداخل بين الأدوار."},{"title":"ضبط الصلاحيات والسياسات","description":"توزيع مسؤوليات التنفيذ والمراجعة والاعتماد، وصياغة السياسات والتحقق من اتساقها مع الهيكل واللوائح."},{"title":"تطوير الإجراءات وأدواتها","description":"تحسين خطوات العمليات ذات الأولوية، وتحديد مسؤولياتها ومدخلاتها ومخرجاتها، وإعداد النماذج اللازمة لتنفيذها وتوثيقها."},{"title":"إعداد الخطة التشغيلية","description":"تحويل الأهداف الاستراتيجية إلى أنشطة ومخرجات سنوية، وتحديد المسؤوليات والمواعيد والموارد ومؤشرات الإنجاز."},{"title":"بناء المتابعة والتحقق من الاتساق","description":"تجهيز لوحة المؤشرات وآلية تحديثها، ومراجعة ترابط مكونات البناء المؤسسي ومعالجة التعارضات والنواقص."}]$c$::jsonb,
    target_audience = $c$["الجمعيات الأهلية التي تحتاج إلى تأسيس بنائها المؤسسي أو تطويره وتنظيم أعمالها."]$c$::jsonb,
    updated_at = NOW()
WHERE title = $c$مركز البناء المؤسسي$c$;

UPDATE enablement_centers SET
    overview = $c$يربط احتياجات الجمعيات بفرص التدريب التعاوني، من خلال تصميم فرص مناسبة، ومطابقة المتدربين بها، وتجهيز برامج التهيئة وأدوات التقييم، وتوثيق نتائج التجربة والأعمال المنجزة. ويساعد الجمعيات على تحويل احتياجاتها إلى مهام تدريبية واضحة، تتيح للمتدربين اكتساب خبرة عملية وتقديم مخرجات تستفيد منها الجمعية.$c$,
    short_description = $c$يربط احتياجات الجمعيات بفرص التدريب التعاوني، من خلال…$c$,
    outputs = $c$["بطاقات فرص التدريب التعاوني.","سجل المرشحين ونتائج الاختيار والمطابقة.","برنامج تهيئة المتدربين.","أدوات تقييم أداء المتدربين وتعلّمهم وقياس رضا المشاركين.","تقرير إنجاز برنامج التدريب ومخرجاته."]$c$::jsonb,
    methodology = $c$[{"title":"تحليل الاحتياج وتصميم الفرص","description":"تحديد الأعمال والتخصصات المناسبة، وبناء فرص تتضمن أهداف التعلم والمهام والمخرجات والمدة ومتطلبات الاستضافة."},{"title":"بناء معايير الاختيار","description":"تحديد شروط الترشح ومعايير المفاضلة، وتجهيز أدوات استقبال الطلبات وفحصها وتقييم ملاءمة المرشحين."},{"title":"تنفيذ الترشيح والمطابقة","description":"مراجعة ملفات المرشحين ومطابقتهم بالفرص، وتنسيق الاختيار وتوثيق الأدوار والتوقعات بين الأطراف."},{"title":"تجهيز التهيئة والتقييم","description":"إعداد برنامج تعريف المتدرب بالجمعية ودوره، وتصميم أدوات تقييم الأداء والتعلم وقياس رضا الجمعية والمتدرب."},{"title":"تحليل نتائج التجربة وتوثيقها","description":"تجميع الأعمال والتقييمات ونتائج الرضا، وتحليل تحقق أهداف التدريب وتوثيق المخرجات وفرص التحسين."}]$c$::jsonb,
    target_audience = $c$["الجمعيات الأهلية المستضيفة للتدريب التعاوني، والطلاب والطالبات المرشحون للتدريب في تخصصات تتوافق مع احتياجاتها."]$c$::jsonb,
    updated_at = NOW()
WHERE title = $c$مركز التدريب التعاوني$c$;

UPDATE enablement_centers SET
    overview = $c$يطوّر طريقة تعريف الجمعية بنفسها وإبراز قيمة برامجها وأثرها، من خلال تشخيص حضورها الاتصالي، وتوحيد رسائلها، وإعداد ملفها التعريفي وخطة محتواها، وإنتاج نصوص وقصص ومواد إعلامية تستند إلى شواهد موثوقة. ويساعدها على تقديم صورة واضحة ومتسقة أمام جمهورها، تعكس حقيقة أعمالها وتوضح فرص الاستفادة منها والتعاون معها.$c$,
    short_description = $c$يطوّر طريقة تعريف الجمعية بنفسها وإبراز قيمة برامجها…$c$,
    outputs = $c$["تقرير الوضع الراهن الاتصالي والإعلامي وأولويات التحسين.","الملف التعريفي للجمعية.","خطة محتوى لحسابات التواصل.","النصوص التعريفية وقصص الأثر والمواد الإعلامية.","التقرير الإعلامي وفهرس الشواهد."]$c$::jsonb,
    methodology = $c$[{"title":"تحليل الحضور الاتصالي","description":"مراجعة تعريف الجمعية ورسائلها وموادها وقنواتها، وتحليل بيانات التفاعل المتاحة لتحديد الفجوات وأولويات التحسين."},{"title":"بناء التعريف المؤسسي","description":"تنظيم معلومات الجمعية وبرامجها وقدراتها وشواهد عملها، وصياغتها في ملف تعريفي واضح ومتسق مع هويتها."},{"title":"تخطيط المحتوى","description":"تحديد الجمهور والرسائل والمحاور، وتوزيع الموضوعات على القنوات والفترة المستهدفة، مع تحديد أشكال المواد ومسؤوليات إنتاجها."},{"title":"تطوير النصوص وقصص الأثر","description":"مراجعة الشواهد والموافقات، وكتابة النصوص والقصص التي تُظهر التغير الموثق، وتكييفها للقنوات المختارة."},{"title":"إنتاج المواد البصرية","description":"تصميم المواد بالمقاسات المتفق عليها، والتحقق من اتساقها مع الهوية ودقة النصوص وحقوق الاستخدام."},{"title":"توثيق المخرجات وتحليل البيانات المتاحة","description":"تنظيم المواد والشواهد، وتجميع بيانات النشر التي توفرها الجمعية، وإعداد تقرير بالمنجز والنتائج وفرص التحسين."}]$c$::jsonb,
    target_audience = $c$["الجمعيات الأهلية التي تحتاج إلى تحسين تعريفها وحضورها الإعلامي وإبراز برامجها وأثرها أمام المستفيدين والشركاء والمانحين."]$c$::jsonb,
    updated_at = NOW()
WHERE title = $c$مركز تحسين الصورة الذهنية$c$;

UPDATE enablement_centers SET
    overview = $c$يساعد الجمعيات على فهم التغيرات المرتبطة ببرامجها ومبادراتها، من خلال بناء إطار للقياس، وجمع البيانات وتحليلها، وتفسير النتائج وحدودها، واستخلاص توصيات لتحسين البرامج ودعم القرارات. ويوفّر أدلة تساعد على معرفة ما تحقق للمستفيدين، وتحديد جوانب الفاعلية وفرص التطوير، وعرض النتائج بصورة واضحة أمام الشركاء والمانحين.$c$,
    short_description = $c$يساعد الجمعيات على فهم التغيرات المرتبطة ببرامجها ومبادراتها…$c$,
    outputs = $c$["إطار قياس الأثر ومؤشراته وخطة جمع البيانات.","أدوات القياس وقاعدة البيانات ودليل المؤشرات.","تقرير قياس الأثر والنتائج والتوصيات.","ملخص تنفيذي لأبرز النتائج ودلالاتها."]$c$::jsonb,
    methodology = $c$[{"title":"تحليل منطق البرنامج","description":"دراسة الاحتياج والفئات والأنشطة والمخرجات، وتحديد التغيرات المتوقعة والافتراضات التي تربط التدخل بنتائجه."},{"title":"بناء إطار القياس","description":"تحديد أسئلة القياس والمؤشرات وطرق احتسابها ومصادرها وفتراتها، ومراجعة توافر خط أساس أو بيانات سابقة."},{"title":"تصميم منهجية جمع البيانات","description":"اختيار أساليب القياس والعينة والمقارنات المناسبة، وإعداد الأدوات واختبار وضوحها وملاءمتها."},{"title":"جمع البيانات وضبط جودتها","description":"جمع البيانات وتنظيمها وتنظيفها، والتحقق من اكتمالها واتساقها وتوثيق النواقص المؤثرة في التحليل."},{"title":"تحليل التغيرات وتفسيرها","description":"تحليل النتائج ومقارنتها بالمستهدفات أو البيانات المرجعية، ودراسة العوامل المفسرة للتغير وحدود نسبته إلى البرنامج."},{"title":"استخلاص النتائج والتوصيات","description":"ربط النتائج بأسئلة القياس وقرارات الجمعية، وتحديد فرص التحسين، وإعداد تقرير يوضح الأدلة والاستنتاجات وحدودها."}]$c$::jsonb,
    target_audience = $c$["الجمعيات الأهلية التي تحتاج إلى قياس نتائج برامجها والتغيرات لدى المستفيدين، وتحسين تدخلاتها، وتوثيق أثرها للشركاء والمانحين."]$c$::jsonb,
    updated_at = NOW()
WHERE title = $c$مركز قياس الأثر$c$;

UPDATE enablement_centers SET
    overview = $c$ينتج معرفة موثقة تساعد الجمعيات على فهم الاحتياجات والقضايا المرتبطة بعملها، واستكشاف البدائل، وتصميم البرامج واتخاذ القرارات، من خلال دراسات مكتبية أو ميدانية تُبنى على أسئلة واضحة ومنهجيات مناسبة. ويحوّل المعلومات والبيانات إلى نتائج وتوصيات تدعم تحديد الأولويات وتوجيه الموارد وتطوير استجابات أكثر ملاءمة للمستفيدين والمجتمع.$c$,
    short_description = $c$ينتج معرفة موثقة تساعد الجمعيات على فهم الاحتياجات…$c$,
    outputs = $c$["خطة الدراسة ومنهجيتها وأدواتها.","قاعدة بيانات الدراسة أو مصفوفة مصادرها.","تقرير الدراسة شاملًا التحليل والنتائج والاستنتاجات والتوصيات والمراجع.","ملخص تنفيذي للنتائج والخيارات المقترحة."]$c$::jsonb,
    methodology = $c$[{"title":"صياغة المشكلة وأسئلة الدراسة","description":"تحديد القضية وتحويلها إلى أسئلة قابلة للبحث، وضبط الأهداف والنطاق والفئات المعنية واستخدامات النتائج."},{"title":"مراجعة المعرفة المتاحة","description":"مراجعة الدراسات والتقارير والبيانات السابقة، وتقييم جودتها وصلتها بالموضوع وتحديد الفجوات المعرفية."},{"title":"تصميم الدراسة","description":"اختيار المنهج والمصادر والعينة وأدوات الجمع، وتحديد إجراءات التنفيذ والتحليل وفق أسئلة الدراسة."},{"title":"تطوير الأدوات واختبارها","description":"إعداد أدوات الدراسة وتجربتها وتعديلها، للتحقق من وضوحها وقدرتها على جمع المعلومات المطلوبة."},{"title":"تنفيذ جمع البيانات","description":"تنفيذ البحث المكتبي أو العمل الميداني، وتوثيق المصادر وتنظيم البيانات والتحقق من جودتها."},{"title":"التحليل وبناء الاستنتاجات","description":"تحليل البيانات ومقارنتها بالمعرفة السابقة، والإجابة عن أسئلة الدراسة مع توضيح حدود الأدلة والتفسيرات."},{"title":"تطوير التوصيات وإعداد التقرير","description":"صياغة توصيات أو بدائل تدعمها النتائج، وتوضيح مبرراتها، وإعداد التقرير والملخص التنفيذي."}]$c$::jsonb,
    target_audience = $c$["الجمعيات الأهلية التي تحتاج إلى دراسة احتياجات المستفيدين أو المجتمع، أو بحث قضية، أو مقارنة بدائل تدعم تصميم البرامج واتخاذ القرارات."]$c$::jsonb,
    updated_at = NOW()
WHERE title = $c$مركز الدراسات والأبحاث$c$;
